<style>.campus-intro{padding:54px 0 20px}.campus-intro>p{max-width:780px;color:var(--muted-foreground);font-size:17px;line-height:1.7}.campus-paths{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:30px 0 42px}.campus-path{padding:28px;border:1px solid var(--border);border-radius:24px;background:#fff}.campus-path.cat{background:var(--gradient-dark);color:#fff}.campus-path p{color:var(--muted-foreground)}.campus-path.cat p{color:rgba(255,255,255,.7)}.campus-path .btn{margin-top:8px}.campus-filters{display:grid;grid-template-columns:1.2fr 1fr 1fr auto;gap:12px;align-items:end;margin:0 0 26px;padding:18px;border:1px solid var(--border);border-radius:20px;background:var(--muted)}.campus-filters label{font-size:13px;font-weight:600}.campus-filters select,.campus-filters input{margin-top:5px}.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.event-card{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--border);border-radius:24px;background:#fff;transition:.35s var(--ease)}.event-card:hover{transform:translateY(-4px);border-color:var(--primary);box-shadow:var(--shadow-elegant)}.event-card img{width:100%;height:210px;object-fit:cover}.event-info{display:flex;flex:1;flex-direction:column;padding:22px}.event-kicker{display:flex;justify-content:space-between;gap:8px;align-items:center;color:var(--primary-deep);font-size:12px;font-weight:700;text-transform:uppercase}.event-state{padding:4px 8px;border-radius:999px;background:rgba(145,208,37,.13)}.event-state.cancelled{background:#fee2e2;color:#991b1b}.event-info h2{margin:10px 0 8px;font-size:21px}.event-info p{color:var(--muted-foreground);font-size:14px}.event-more{margin-top:auto;padding-top:12px;color:var(--primary-deep);font-weight:700}.empty-campus{grid-column:1/-1;padding:28px;border:1px solid var(--border);border-radius:20px;background:var(--muted);color:var(--muted-foreground)}@media(max-width:900px){.event-grid{grid-template-columns:repeat(2,1fr)}.campus-filters{grid-template-columns:1fr 1fr}}@media(max-width:620px){.campus-paths,.event-grid,.campus-filters{grid-template-columns:1fr}.campus-intro{padding-top:38px}}</style>
<section class="hero"><div class="wrap"><span class="section-label">Formazione e aggiornamento</span><h1>Campus IDEMA</h1><p>Incontri tecnici, approfondimenti e occasioni di confronto dedicate ai professionisti della climatizzazione.</p></div></section>
<section class="campus-intro"><div class="wrap"><h2>Scegli il tuo percorso</h2><p>Consulta gli appuntamenti aperti oppure accedi alla formazione riservata ai Centri Assistenza Tecnica IDEMA.</p><div class="campus-paths"><article class="campus-path"><span class="section-label">Eventi aperti</span><h2>Formazione accessibile a tutti</h2><p>Scopri date, argomenti, relatori e disponibilità. L’iscrizione non richiede un account.</p><a class="btn" href="#eventi-aperti">Consulta gli eventi</a></article><article class="campus-path cat"><span class="section-label">Area CAT</span><h2>Eventi riservati alla rete tecnica</h2><p>Accedi con il tuo account personale oppure invia una nuova richiesta di abilitazione.</p><a class="btn" href="/idemaclima/campus/cat">Accedi all’Area CAT</a></article></div><h2 id="eventi-aperti">Eventi aperti</h2><form class="campus-filters" method="get"><label>Stato<select name="stato"><option value="tutti">Tutti</option><?php foreach(['prossimi'=>'Prossimi','passati'=>'Passati','annullati'=>'Annullati'] as $v=>$l):?><option value="<?=$v?>" <?=($filters['status']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Mese<input type="month" name="mese" value="<?=e($filters['month']??'')?>"></label><label>Categoria<select name="categoria"><option value="">Tutte</option><?php foreach($categories as $c):?><option <?=($filters['category']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><button class="btn" type="submit">Filtra</button></form><div class="event-grid"><?php foreach($events as $event):$cancelled=(int)$event['cancelled']===1;$past=strtotime((string)$event['starts_at'])<time();?><a class="event-card" href="/idemaclima/campus/<?=e($event['slug'])?>"><?php if(!empty($event['cover_image'])):?><img src="<?=e($event['cover_image'])?>" alt="<?=e($event['title'])?>"><?php endif;?><div class="event-info"><div class="event-kicker"><span><?=e($event['category']?:'Campus IDEMA')?></span><span class="event-state <?=$cancelled?'cancelled':''?>"><?=$cancelled?'Annullato':($past?'Concluso':'In programma')?></span></div><h2><?=e($event['title'])?></h2><span class="meta"><?=e(date('d/m/Y · H:i',strtotime((string)$event['starts_at'])))?><?=!empty($event['location'])?' · '.e($event['location']):''?></span><?php if(!empty($event['short_description'])):?><p><?=e($event['short_description'])?></p><?php endif;?><span class="event-more">Scopri l’evento →</span></div></a><?php endforeach;?><?php if(!$events):?><div class="empty-campus">Nessun evento corrisponde ai filtri selezionati.</div><?php endif;?></div></div></section>
